package com.bankpli.javabank.transfer;import java.math.*;import java.util.List;import org.springframework.stereotype.Service;
@Service public class FeeCalculator {private record Tier(BigDecimal min,BigDecimal max,BigDecimal base,BigDecimal rate){}private static final List<Tier>TIERS=List.of(t("0","100","0","0"),t("100.01","1000","2.50","0.005"),t("1000.01","10000","5","0.010"),t("10000.01","100000","25","0.015"),t("100000.01","99999999.99","100","0.020"));private static Tier t(String a,String b,String c,String d){return new Tier(new BigDecimal(a),new BigDecimal(b),new BigDecimal(c),new BigDecimal(d));}public BigDecimal calculate(BigDecimal amount,Priority priority,TransferType type){Tier tier=TIERS.stream().filter(x->amount.compareTo(x.min)>=0&&amount.compareTo(x.max)<=0).findFirst().orElseThrow(()->new IllegalArgumentException("Amount outside fee schedule"));BigDecimal multiplier=switch(priority){case STANDARD->BigDecimal.ONE;case HIGH->new BigDecimal("1.5");case URGENT->new BigDecimal("2");};BigDecimal adjustment=switch(type){case INTERNAL->BigDecimal.ZERO;case EXTERNAL->new BigDecimal("5");case WIRE->new BigDecimal("25");};return tier.base.add(amount.multiply(tier.rate)).multiply(multiplier).add(adjustment).setScale(2,RoundingMode.HALF_UP);}}
